from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 260, "תרשים א: מסילה חלקה ובקצה השמאלי קיר. על המסילה גופים A ו-B מחוברים בקפיץ דרוך, וגוף C מימינם. תרשים ב: הכוח שהקיר מפעיל על A כפונקציה של הזמן, משולש שמגיע לשיא ב-0.04 שניות וחוזר לאפס ב-0.08")
    g.rect(40, 20, 12, 110, fill="url(#f-hatch)", stroke="none", width=0); g.line(52, 20, 52, 130, width=2); g.heb(70, 34, "קיר", anchor="start")
    g.line(52, 120, 520, 120, width=2)
    g.block(130, 104, 40, 30, "A"); g.spring(150, 104, 190, 104, coils=4, amp=5); g.block(210, 104, 40, 30, "B"); g.block(400, 102, 60, 34, "C")
    X, Y = g.graph(170, 240, 220, 90, "t (s)", "F (N)", xticks=[(0.04, "0.04"), (0.08, "0.08")], xmax=0.1, ymax=1.2, grid=False)
    g.plot(X, Y, [(0, 0), (0.04, 1), (0.08, 0)]); g.line(X(0.04), Y(1), X(0.04), Y(0), stroke="var(--d-dim)", width=1, dash="4 3")
    return g

E(id="bagrut-2011-q3", year=2011, label="2011 שאלה 3", topic="momentum", sub="mom-impulse", diff=3, fig=fig,
  stem=r"תרשים א מראה מסילה חלקה ועליה שלושה גופים, $A$, $B$ ו-$C$, שנעים עליה בלי חיכוך. בקצה המסילה יש קיר. הגופים $A$ ו-$B$ מחוברים בקפיץ קל מכווץ. נתון: $m_A = 0.1\,\text{kg}$, $m_B = 0.2\,\text{kg}$. משחררים את הקפיץ, והגופים $A$ ו-$B$ מתחילים לנוע.",
  parts=[
    P("א1", r"מה התנע של המערכת של $A$ ו-$B$ מיד אחרי שהקפיץ משתחרר? הסבירו.", num(0, "kg·m/s"), ["principle"], [
        X(r"הכיוון החיובי הוא לכיוון הקיר. בתשובות כותבים גודל, ואת הכיוון במילים."),
        S(r"התחלה ממנוחה", r"כוח הקפיץ פנימי, ואין כוח חיצוני אופקי. לפני השחרור הגופים במנוחה, ולכן התנע נשאר אפס", r"p_A + p_B = 0", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
    ], r"$0$", key=r"0"),
    P("א2", r"מיד אחרי השחרור, $A$ נע לכיוון הקיר במהירות $v_A = 0.6\,\text{m/s}$. מה המהירות של $B$ באותו רגע (גודל וכיוון)?", num(0.3, "m/s"), ["principle", "signs"], [
        S(r"שימור תנע", r"התנע הכולל אפס", r"0 = 0.1 \cdot 0.6 + 0.2\,v_B \;\Rightarrow\; v_B = -0.3\,\text{m/s}", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
    ], r"$0.3\,\text{m/s}$, הרחק מהקיר", key=r"vB=−0.3 m/s"),
    P("ב1", r"$A$ מתנגש בקיר התנגשות אלסטית. מה המהירות של $A$ (גודל וכיוון) מיד אחרי ההתנגשות? הסבירו.", num(0.6, "m/s"), ["principle"], [
        S(r"התנגשות אלסטית בקיר כבד", r"הקיר לא זז ולא מקבל אנרגיה. האנרגיה הקינטית של הגוף נשמרת, ולכן גודל המהירות נשמר והכיוון מתהפך", r"u_A = -0.6\,\text{m/s}", eq=r"E_k = \tfrac{1}{2}mv^2"),
    ], r"$0.6\,\text{m/s}$, הרחק מהקיר", key=r"0.6 m/s"),
    P("ב2", r"מה גודל המתקף שהקיר מפעיל על $A$, ומה כיוונו?", num(0.12, "N·s"), ["principle", "signs"], [
        S(r"המתקף שווה לשינוי התנע", r"המהירות הסופית פחות ההתחלתית, עם הסימנים", r"J = 0.1\,(-0.6) - 0.1 \cdot 0.6 = -0.12\,\text{N}\cdot\text{s}", eq=r"\vec J_{\text{tot}} = \Delta\vec p"),
    ], r"$0.12\,\text{N}\cdot\text{s}$, הרחק מהקיר", key=r"J=−0.12 N·s"),
    P("ג1", r"הגרף בתרשים ב מראה את גודל הכוח שהקיר מפעיל על $A$ כפונקציה של הזמן. מה מייצג השטח שבין הגרף לציר הזמן?", choice(["את המתקף", "את העבודה", "את השינוי באנרגיה הקינטית", "את התאוצה"], 0), ["graph", "principle"], [
        S(r"שטח מתחת לגרף כוח-זמן", r"בכל פרק זמן קצר השטח הוא כוח כפול זמן, וזה המתקף. כשהכוח משתנה, מחברים את כל הפרקים, וזה השטח כולו", r"J = F\,\Delta t"),
    ], r"את המתקף", key=r"המתקף"),
    P("ג2", r"בעזרת הגרף, מה הגודל המרבי של הכוח שהקיר הפעיל על $A$ בזמן ההתנגשות?", num(3, "N"), ["graph", "algebra"], [
        S(r"שטח המשולש", r"השטח שווה לגודל המתקף מהסעיף הקודם", r"\tfrac{1}{2} \cdot 0.08 \cdot F_{\max} = 0.12"),
        S(r"פותרים", r"מבודדים את הכוח המרבי", r"F_{\max} = \frac{0.12}{0.04} = 3\,\text{N}"),
    ], r"$3\,\text{N}$", key=r"Fmax=3 N"),
    P("ד1", r"$B$, שנע במהירות מסעיף א2, מתנגש בגוף $C$ שמסתו $m_C = 0.4\,\text{kg}$ ונע לקראתו. שני הגופים נדבקים זה לזה. מיד אחרי ההתנגשות האנרגיה הקינטית של שניהם יחד היא אפס. מה הייתה המהירות של $C$ לפני ההתנגשות?", num(0.15, "m/s"), ["principle"], [
        S(r"אנרגיה אפס אחרי", r"אם האנרגיה הקינטית אפס, הגופים עומדים, ולכן התנע הכולל אחרי ההתנגשות אפס. לכן גם לפניה", r"0.2\,(-0.3) + 0.4\,v_C = 0", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"פותרים", r"מבודדים את מהירות הגוף", r"v_C = \frac{0.06}{0.4} = 0.15\,\text{m/s}"),
    ], r"$0.15\,\text{m/s}$", key=r"vC=0.15 m/s"),
    P("ד2", r"אם המהירות של $C$ לפני ההתנגשות קטנה מזו שמצאתם בסעיף ד1, לאיזה כיוון ינועו $B$ ו-$C$ אחרי שנדבקו? ענו בלי חישוב.", choice(["בכיוון שבו נע B", "בכיוון שבו נע C", "לא ינועו"], 0), ["principle"], [
        S(r"התנע של הגוף הראשון גדול יותר", r"עכשיו התנע של הגוף הראשון גדול בגודלו מהתנע של השני, ולכן התנע הכולל הוא בכיוון שבו הוא נע. התנע נשמר", r"m_B |v_B| > m_C |v_C|"),
    ], r"בכיוון שבו נע $B$", key=r"הגופים ינועו יחד בכיוון B"),
  ],
  concepts=["שימור תנע", "מתקף", "שטח מתחת לגרף כוח-זמן", "התנגשות פלסטית"],
  summary=r"שני גופים שקפיץ דוחף, ניתור מקיר, מתקף מגרף משולש, והתנגשות פלסטית שעוצרת הכול.",
  review="הנחה שלי.\nבחישובים הכיוון החיובי הוא לכיוון הקיר, אבל התלמיד עונה בגדלים ואת הכיוון כותבים במילים.\nמה לבדוק: רק לאשר.")
